CREATE TABLE IF NOT EXISTS config (id INTEGER PRIMARY KEY CHECK(id=1), version INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS dining_tables (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS visits (id TEXT PRIMARY KEY, table_id INTEGER NOT NULL REFERENCES dining_tables(id), status TEXT NOT NULL CHECK(status IN ('open','payment_pending','closed')), state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 0, pending INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_visit ON visits(table_id) WHERE status != 'closed';
CREATE INDEX IF NOT EXISTS visit_pending ON visits(pending,created_at);
CREATE INDEX IF NOT EXISTS visit_recent ON visits(created_at DESC);
CREATE TABLE IF NOT EXISTS limits (key TEXT PRIMARY KEY, hits INTEGER NOT NULL DEFAULT 0, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS locks (key TEXT PRIMARY KEY, until_at INTEGER NOT NULL, token TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (hash TEXT PRIMARY KEY, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS updates (key TEXT PRIMARY KEY, expires INTEGER NOT NULL, done INTEGER NOT NULL DEFAULT 0);
